//! Reports are a pure function of the result files: the same JSON renders
//! the same bytes (`report --table`), and the marked tables of a document
//! are regenerated byte for byte (`report --update` / `--check`).

use std::path::{Path, PathBuf};
use std::process::Command;

use gstore_bench::gates::Thresholds;
use gstore_bench::report::{render_args, splice, table, END};
use gstore_bench::schema::*;
use gstore_bench::workload::WorkloadSpec;

struct Tmp(PathBuf);

impl Tmp {
    fn new(name: &str) -> Tmp {
        let p = std::env::temp_dir().join(format!("gsb-report-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&p);
        std::fs::create_dir_all(&p).unwrap();
        Tmp(p)
    }

    fn path(&self, rel: &str) -> String {
        self.0.join(rel).to_string_lossy().into_owned()
    }
}

impl Drop for Tmp {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn run(backend: &str, label: Option<&str>, f: f64) -> BackendRun {
    let mut r = BackendRun::new(backend);
    r.label = label.map(str::to_string);
    r.build = Some(BuildResult {
        wall_ms: 1500.0 * f,
        peak_rss_mib: Some(100.0),
        dir_bytes: 12_345_678,
        summary: (backend == "disk").then(|| BuildSummary {
            phases_ms: vec![("parse+encode".into(), 900.0), ("index".into(), 120.0)],
            budget_mib: Some(1024.0),
            budget_peak_mib: Some(40.5),
            term_map_mib: Some(4.0),
            threads: Some(2),
            spilled_runs: Some(0),
            spilled_mib: Some(0.0),
        }),
        ..BuildResult::default()
    });
    r.open = Some(OpenResult {
        first_ms: 30.0 * f,
        warm_ms: 25.0 * f,
        rss_after_open_mib: Some(50.0),
        triple_num: 100,
        ..OpenResult::default()
    });
    r.queries = ["q1", "q2"]
        .iter()
        .enumerate()
        .map(|(i, n)| QueryMeasure {
            name: n.to_string(),
            rows: 3 + i as u64,
            rows_fnv64: format!("{:016x}", 7 + i),
            first_ms: 2.0 * f,
            median_ms: (1.0 + i as f64) * f,
            stable: true,
            ..QueryMeasure::default()
        })
        .collect();
    r.mixed = Some(MixedResult {
        points: vec![MixedPoint {
            endpoint: "sparql".into(),
            query: "q2".into(),
            readers: 8,
            check_point: true,
            write_every_ms: 100,
            secs: 5.0,
            reads: 1000,
            qps: 200.0 / f,
            writes: 50,
            distinct_bodies: 1,
            ..MixedPoint::default()
        }],
        bodies_equal: true,
        writes_ok: true,
        hwm_mib: None,
        begin: Some(BeginPoint {
            samples: 20,
            median_ms: 1.5 * f,
            p95_ms: 2.0 * f,
            max_ms: 3.0 * f,
            rss_growth_first_mib: Some(0.5),
            rss_growth_max_mib: Some(1.0),
        }),
    });
    r
}

fn result(f: f64, runs: Vec<BackendRun>) -> BenchResult {
    BenchResult {
        schema: SCHEMA.into(),
        kind: "result".into(),
        provisional: false,
        note: None,
        profile: "reference".into(),
        created_unix: 0,
        env: EnvInfo::default(),
        calibration: None,
        workload: WorkloadInfo {
            spec: WorkloadSpec::lubm(8, 0),
            id: "lubm-like".into(),
            version: "lubm-like/1".into(),
            lines: 110,
            unique_triples: 100,
            bytes: 1000,
            data_fnv64: "00000000000000aa".into(),
            queries: ["q1", "q2"]
                .iter()
                .map(|n| QueryInfo {
                    name: n.to_string(),
                    text_fnv64: "0000000000000001".into(),
                    bindings: Vec::new(),
                    tries: None,
                })
                .collect(),
            chunk: None,
            gen_ms: None,
        },
        runs,
        extra_workloads: vec![WorkloadSection {
            workload: WorkloadInfo {
                spec: WorkloadSpec::watdiv(10, 0),
                id: "watdiv-like".into(),
                version: "watdiv-like/1".into(),
                lines: 100,
                unique_triples: 100,
                bytes: 1000,
                data_fnv64: "00000000000000bb".into(),
                queries: vec![QueryInfo {
                    name: "q1".into(),
                    text_fnv64: "0000000000000002".into(),
                    bindings: vec![("v1".into(), "wsdbm:Website3".into())],
                    tries: Some(2),
                }],
                chunk: None,
                gen_ms: None,
            },
            runs: vec![run("snapshot", None, f)],
        }],
    }
}

/// The overview table of a final result against a pre-Phase-6 one: the
/// labelled disk runs are compared with the baseline's unlabelled disk run.
const GOLDEN_OVERVIEW: &str = "\
| workload | backend | build s | build peak MiB | dir MB | open first ms | open warm ms | RSS after open MiB | query HWM MiB | geomean ms | build vs base | open vs base | geomean vs base |
|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|
| lubm-like univ 8 | snapshot | 0.75 | 100.0 | 12.3 | 15.0 | 12.5 | 50.0 | – | 0.71 | 0.50× | 0.50× | 0.50× |
| lubm-like univ 8 | disk@stream | 0.75 | 100.0 | 12.3 | 15.0 | 12.5 | 50.0 | – | 0.71 | 0.50× | 0.50× | 0.50× |
| lubm-like univ 8 | disk@materialize | 1.50 | 100.0 | 12.3 | 30.0 | 25.0 | 50.0 | – | 1.41 | 1.00× | 1.00× | 1.00× |
| watdiv-like scale 10 | snapshot | 0.75 | 100.0 | 12.3 | 15.0 | 12.5 | 50.0 | – | 0.71 | 0.50× | 0.50× | 0.50× |

";

fn final_and_pre() -> (BenchResult, BenchResult) {
    let fin = result(
        0.5,
        vec![
            run("snapshot", None, 0.5),
            run("disk", Some("stream"), 0.5),
            run("disk", Some("materialize"), 1.0),
        ],
    );
    let pre = result(
        1.0,
        vec![run("snapshot", None, 1.0), run("disk", None, 1.0)],
    );
    (fin, pre)
}

#[test]
fn tables_are_deterministic_and_compare_labelled_runs() {
    let (fin, pre) = final_and_pre();
    let t = Thresholds::default();
    let a = table("overview", &[(fin.clone(), Some(pre.clone()))], &t).unwrap();
    assert_eq!(a, GOLDEN_OVERVIEW, "\n{a}");
    for kind in [
        "queries", "build", "update", "conc", "mixed", "gates", "full",
    ] {
        let x = table(kind, &[(fin.clone(), Some(pre.clone()))], &t).unwrap();
        let y = table(kind, &[(fin.clone(), Some(pre.clone()))], &t).unwrap();
        assert_eq!(x, y, "{kind} is not deterministic");
    }
    let q = table("queries", &[(fin.clone(), Some(pre.clone()))], &t).unwrap();
    assert!(q.contains("**watdiv-like scale 10**"), "{q}");
    assert!(
        q.contains("| q2 | 4 | 1.00 | 1.00 | 0.50× | 1.00 | 1.00 | 0.50× | 2.00 | 2.00 | 1.00× |"),
        "{q}"
    );
    let b = table("build", &[(fin.clone(), None)], &t).unwrap();
    assert!(
        b.contains("| lubm-like univ 8 | disk@stream | parse+encode 900, index 120 | 1024.0 | 40.5 | 4.0 | 2 | 0 | 0.0 |"),
        "{b}"
    );
    let m = table("mixed", &[(fin.clone(), Some(pre.clone()))], &t).unwrap();
    assert!(m.contains("| sparql | on | q2 | 8 | 400.0 |"), "{m}");
    assert!(table("nope", &[(fin.clone(), None)], &t).is_err());
    assert!(
        table("gates", &[(fin, None)], &t).is_err(),
        "gates needs a baseline"
    );
}

#[test]
fn marked_tables_are_spliced_byte_for_byte() {
    let tmp = Tmp::new("splice");
    let (fin, pre) = final_and_pre();
    let (f, p) = (tmp.path("final.json"), tmp.path("pre.json"));
    fin.save(Path::new(&f)).unwrap();
    pre.save(Path::new(&p)).unwrap();
    let t = Thresholds::default();
    let args = format!("--table overview {f} --compare {p}");
    let doc = format!(
        "# Title\n\nSome text.\n\n<!-- gstore-bench report {args} -->\nold table\n{END}\n\nAfter.\n"
    );
    let mut render =
        |a: &[String]| -> Result<String, String> { render_args(a, &Thresholds::default()) };
    let (fresh, changed) = splice(&doc, &mut render).unwrap();
    assert_eq!(changed, vec![args.clone()]);
    assert_eq!(
        fresh,
        format!(
            "# Title\n\nSome text.\n\n<!-- gstore-bench report {args} -->\n{}{END}\n\nAfter.\n",
            GOLDEN_OVERVIEW.trim_end_matches('\n').to_string() + "\n"
        )
    );
    // Regenerating an up-to-date document changes nothing.
    let (again, changed) = splice(&fresh, &mut render).unwrap();
    assert_eq!(again, fresh);
    assert!(changed.is_empty());
    // Malformed markers are errors.
    assert!(splice(
        "<!-- gstore-bench report --table overview x.json -->\n",
        &mut render
    )
    .is_err());
    let _ = t;

    // Through the binary: --check fails on a stale table, --update fixes it,
    // then --check passes and the bytes are the library's.
    let exe = env!("CARGO_BIN_EXE_gstore-bench");
    let readme = tmp.path("README.md");
    std::fs::write(&readme, &doc).unwrap();
    let st = Command::new(exe)
        .args(["report", "--check", &readme])
        .output()
        .unwrap();
    assert_eq!(st.status.code(), Some(1), "{st:?}");
    let st = Command::new(exe)
        .args(["report", "--update", &readme])
        .output()
        .unwrap();
    assert!(st.status.success(), "{st:?}");
    assert_eq!(std::fs::read_to_string(&readme).unwrap(), fresh);
    let st = Command::new(exe)
        .args(["report", "--check", &readme])
        .output()
        .unwrap();
    assert!(st.status.success(), "{st:?}");
    // Several documents at once: a stale second one fails the check.
    let changelog = tmp.path("CHANGELOG.md");
    std::fs::write(&changelog, &doc).unwrap();
    let st = Command::new(exe)
        .args(["report", "--check", &readme, &changelog])
        .output()
        .unwrap();
    assert_eq!(st.status.code(), Some(1), "{st:?}");
    assert!(String::from_utf8_lossy(&st.stderr).contains("CHANGELOG.md: stale table"));
    let st = Command::new(exe)
        .args(["report", "--update", &readme, &changelog])
        .output()
        .unwrap();
    assert!(st.status.success(), "{st:?}");
    assert_eq!(std::fs::read_to_string(&changelog).unwrap(), fresh);
    let st = Command::new(exe)
        .args(["report", "--check", &readme, &changelog])
        .output()
        .unwrap();
    assert!(st.status.success(), "{st:?}");
    assert_eq!(
        Command::new(exe)
            .args(["report", "--check"])
            .output()
            .unwrap()
            .status
            .code(),
        Some(2)
    );
    // `report ARGS` prints exactly the marked table.
    let out = Command::new(exe)
        .args(["report", "--table", "overview", &f, "--compare", &p])
        .output()
        .unwrap();
    assert!(out.status.success());
    assert_eq!(String::from_utf8(out.stdout).unwrap(), GOLDEN_OVERVIEW);
}

#[test]
fn committed_results_still_load_and_compare() {
    // Every result and baseline of earlier rounds (schema gstore-bench/1)
    // reads, self-checks and renders with this version.
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let mut n = 0;
    for dir in ["results", "baselines"] {
        for e in std::fs::read_dir(root.join(dir)).unwrap() {
            let p = e.unwrap().path();
            if p.extension().and_then(|x| x.to_str()) != Some("json") {
                continue;
            }
            let r = BenchResult::load(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()));
            let v = gstore_bench::gates::verdict(&gstore_bench::gates::self_check(&r));
            assert_eq!(
                v,
                gstore_bench::gates::Verdict::Pass,
                "{} fails its self-check",
                p.display()
            );
            assert!(!table("overview", &[(r, None)], &Thresholds::default())
                .unwrap()
                .is_empty());
            n += 1;
        }
    }
    assert!(n >= 10, "only {n} result files found");
    // A pre-Phase-6 file compares with itself (every gate passes).
    let pre = BenchResult::load(&root.join("results/pre-phase6-lubm8.json")).unwrap();
    let o = gstore_bench::gates::evaluate(&pre, &pre, &Thresholds::default(), 1.0);
    assert_eq!(
        gstore_bench::gates::verdict(&o),
        gstore_bench::gates::Verdict::Pass
    );
}
